function rts_add_unit(mysqli $db,int $battle,string $side,string $key,int $qty,array $d): void { $qty=max(1,$qty);$h=(int)$d['hull'];$sh=(int)$d['shield'];$p=(int)($d['position']??2);$name=$db->real_escape_string((string)$d['name']);$class=$db->real_escape_string((string)$d['class']);$sideSafe=$side==='ai'?'ai':'player';$keySafe=$db->real_escape_string($key);$sql="INSERT INTO rts_battle_units (battle_id,side,unit_key,unit_name,class_name,quantity,hull,max_hull,shield,max_shield,armor,attack,defense,range_stat,speed,initiative,morale,ammo,energy_draw,position) VALUES (".(int)$battle.",'".$sideSafe."','".$keySafe."','".$name."','".$class."',".$qty.",".$h.",".$h.",".$sh.",".$sh.",".(int)$d['armor'].",".(int)$d['attack'].",".(int)$d['defense'].",".(int)$d['range'].",".(int)$d['speed'].",".(int)$d['initiative'].",100,100,".(int)$d['energy'].",".$p.")";$db->query($sql); }
function rts_alive(array $u): bool { return (int)$u['quantity']>0 && (int)$u['hull']>0 && $u['status']!=='destroyed'; }
function rts_units(mysqli $db,int $battle): array { $out=[];$q=$db->query('SELECT * FROM rts_battle_units WHERE battle_id='.$battle.' ORDER BY initiative DESC,unit_id ASC');if($q)while($r=$q->fetch_assoc())$out[]=$r;return $out; }
function rts_save_unit(mysqli $db,array $u): void { $st=$db->prepare("UPDATE rts_battle_units SET quantity=?,hull=?,shield=?,morale=?,ammo=?,position=?,status=? WHERE unit_id=?");if($st){$qty=(int)$u['quantity'];$h=(int)$u['hull'];$sh=(int)$u['shield'];$mor=(int)$u['morale'];$ammo=(int)$u['ammo'];$pos=(int)$u['position'];$status=$qty<=0||$h<=0?'destroyed':(string)$u['status'];$id=(int)$u['unit_id'];$st->bind_param('iiiiiisi',$qty,$h,$sh,$mor,$ammo,$pos,$status,$id);$st->execute();}}
function rts_target(array $units,string $side,?int $wanted=null): ?int { if($wanted){foreach($units as $u)if((int)$u['unit_id']===$wanted&&$u['side']!==$side&&rts_alive($u))return $wanted;}foreach($units as $u)if($u['side']!==$side&&rts_alive($u))return (int)$u['unit_id'];return null; }
function rts_event(mysqli $db,int $battle,int $mission,int $wave,string $type,string $message,array $payload=[]): void { $json=json_encode($payload,JSON_UNESCAPED_SLASHES);$st=$db->prepare('INSERT INTO rts_battle_events (battle_id,mission_id,wave_no,event_type,message,payload_json) VALUES (?,?,?,?,?,?)');if($st){$st->bind_param('iiiiss',$battle,$mission,$wave,$type,$message,$json);$st->execute();} }
function rts_mission_setup(mysqli $db,int $battle,int $uid,string $type,string $theater,int $maxWaves): int { $objectives=['assault'=>'Break every defense wave and secure the theater','defense'=>'Survive every attack wave and protect the command site','raid'=>'Strike the target, seize salvage, and withdraw','intercept'=>'Stop the hostile fleet before it reaches the gate','siege'=>'Destroy layered defenses across orbital and surface phases','escort'=>'Protect the convoy through every hostile wave','expedition'=>'Explore the frontier and return with intelligence'];$targetType=$theater==='planetary'?'planet':($theater==='moon'?'moon':($theater==='station'?'station':'fleet'));$targetName=ucfirst($theater).' Command Target';$reward=5000*$maxWaves;$st=$db->prepare('INSERT INTO rts_missions (battle_id,uid,mission_type,objective,phase,status,current_wave,max_waves,target_name,target_class,reward_metal,reward_crystal,reward_deuterium) VALUES (?,?,?,?,\'orbital\',\'active\',1,?,?,?,?,?,?)');if(!$st)return 0;$objective=$objectives[$type]??$objectives['assault'];$crystal=(int)round($reward*.7);$deut=(int)round($reward*.45);$st->bind_param('iississiii',$battle,$uid,$type,$objective,$maxWaves,$targetName,$theater,$reward,$crystal,$deut);$st->execute();$mid=(int)$db->insert_id;$composition=json_encode(['interceptor'=>3,'frigate'=>2,'cruiser'=>1]);$st2=$db->prepare("INSERT INTO rts_waves (mission_id,wave_no,side,wave_type,status,strength_index,composition_json,spawned_at) VALUES (?,1,'ai','vanguard','active',100,?,NOW())");if($st2){$st2->bind_param('is',$mid,$composition);$st2->execute();}$db->query("INSERT INTO rts_battle_targets (battle_id,target_type,target_name,priority,hull,max_hull,shield,status) VALUES (".$battle.",'".$targetType."','".$db->real_escape_string($targetName)."',90,1000,1000,500,'identified')");rts_event($db,$battle,$mid,1,'mission_started','Mission initiated with an active vanguard wave.',['mission_type'=>$type,'max_waves'=>$maxWaves]);return $mid; }
function rts_spawn_ai_wave(mysqli $db,int $battle,int $mission,int $wave,array $catalog): void { $scale=1+$wave*.35;$groups=[['interceptor',max(2,(int)round(3*$scale))],['frigate',max(1,(int)round(2*$scale))],['cruiser',max(1,(int)round(1*$scale))]];foreach($groups as $g)rts_add_unit($db,$battle,'ai',$g[0],$g[1],$catalog[$g[0]]);$comp=json_encode($groups,JSON_UNESCAPED_SLASHES);$type=$wave%3===0?'siege':($wave%2===0?'reinforcement':'line');$st=$db->prepare("INSERT INTO rts_waves (mission_id,wave_no,side,wave_type,status,strength_index,composition_json,spawned_at) VALUES (?,?, 'ai', ?, 'active', ?, ?, NOW())");if($st){$strength=100+$wave*35;$st->bind_param('iisis',$mission,$wave,$type,$strength,$comp);$st->execute();}rts_event($db,$battle,$mission,$wave,'wave_spawned','A new hostile attack wave has entered the theater.',['wave'=>$wave,'composition'=>$groups]); }

