}
if($action==='order' && ctype_digit($arg)){
 $parts=explode(':',$arg);$unit=(int)($parts[0]??0);$order=(string)($parts[1]??'guard');$target=(int)($parts[2]??0);$allowed=['attack','bombard','intercept','flank','siege','blockade','focus','jam','advance','guard','shield_wall','escort','reinforce','repair','countermeasure','retreat'];$row=rts_one($db,'SELECT battle_id FROM rts_battle_units WHERE unit_id='.$unit.' AND side=\'player\' AND battle_id IN (SELECT battle_id FROM rts_battles WHERE uid='.$uid.' AND status=\'active\') LIMIT 1');if($row&&in_array($order,$allowed,true)){$b=(int)$row['battle_id'];$br=rts_one($db,'SELECT round_no FROM rts_battles WHERE battle_id='.$b.' AND uid='.$uid);$db->query("DELETE FROM rts_battle_orders WHERE battle_id=$b AND unit_id=$unit AND order_round=".(int)$br['round_no']);$st=$db->prepare('INSERT INTO rts_battle_orders (battle_id,unit_id,order_type,target_unit_id,order_round) VALUES (?,?,?,?,?)');if($st){$round=(int)$br['round_no'];$st->bind_param('iisii',$b,$unit,$order,$target,$round);$st->execute();}$status='Order uploaded to the tactical queue.'; $arg=(string)$b;}}
if($action==='retreat' && ctype_digit($arg)){$b=(int)$arg;$db->query("UPDATE rts_battles SET status='retreated' WHERE battle_id=$b AND uid=$uid AND status='active'");$status='Fleet has withdrawn. A tactical report was recorded.';}
if($action==='resolve' && ctype_digit($arg)){
 $bid=(int)$arg;$battle=rts_one($db,'SELECT * FROM rts_battles WHERE battle_id='.$bid.' AND uid='.$uid.' LIMIT 1');
 if(!$battle||$battle['status']!=='active')$error='This battle is not active.';elseif(rts_setting($db,'combat_enabled','1')<0.5)$error='Combat systems are disabled by administrator control.';else{
  $units=rts_units($db,$bid);$round=(int)$battle['round_no']+1;$weaponMult=rts_setting($db,'combat_damage_multiplier','1');$power=0;$log=[];$playerDamage=0;$aiDamage=0;$playerLoss=0;$aiLoss=0;
